Route::redirect('/', '/login');
Route::get('/ready', function () {
    try {
        DB::select('SELECT 1');
        DB::table('jobs')->limit(1)->get(['id']);

        return response()->json(['status' => 'ready']);
    } catch (Throwable) {
        return response()->json(['status' => 'unavailable'], 503);
    }
})->name('readiness');
